declare(strict_types=1);

/**
 * Writes tests/fixtures/nextcloud-api/<major>.php: the public surface, in that release, of every Nextcloud class the
 * app names in lib/ plus NextcloudApiUsage::EXTRA_CLASSES. NextcloudApiContractTest reads these files; nothing in the
 * test suite reads a Nextcloud source tree.
 *
 * Usage: php tests/fixtures/nextcloud-api/generate.php <major> <tree>
 *
 * <tree> is a nextcloud/server checkout of the release in NextcloudApiUsage::SOURCES (lib/public, lib/private/Hooks,
 * lib/base.php, lib/OC.php from 35 on, and apps/dav, apps/files_versions, apps/files_trashbin, apps/files_sharing are enough), with the
 * nextcloud/deck and nextcloud/spreed tags of that row under apps/deck and apps/spreed, and the Circles tag from
 * recipient-sources.json under apps/circles, and the Mail release of mail-sources.json under apps/mail with the
 * server's lib/public/AppFramework/Db (generate-mail.php refreshes the Mail surfaces alone). fetch-recipients.py +
 * generate-recipients.php can reproducibly extend existing fixtures with only the newly used recipient surfaces,
 * checking official archive SHA256 first. The script refuses a tree whose versions differ from that row or from the
 * Mail pin.
 */

use OCA\Mcp\Tests\Unit\Contract\NextcloudApi\FixtureFile;
use OCA\Mcp\Tests\Unit\Contract\NextcloudApi\LibScanner;
use OCA\Mcp\Tests\Unit\Contract\NextcloudApi\MailSourcePins;
use OCA\Mcp\Tests\Unit\Contract\NextcloudApi\NextcloudApiUsage;
use OCA\Mcp\Tests\Unit\Contract\NextcloudApi\SourceParser;

require __DIR__ . '/../../../vendor/autoload.php';

[, $major, $tree] = $argv + [null, null, null];
$expected = NextcloudApiUsage::SOURCES[$major] ?? null;
if ($expected === null || $tree === null || !is_dir($tree)) {
    fwrite(STDERR, "usage: php generate.php <major of NextcloudApiUsage::SOURCES> <tree>\n");
    exit(2);
}

/** @return string the <version> of an app's appinfo/info.xml */
$appVersion = static fn (string $app): string => (string)(simplexml_load_file("$tree/apps/$app/appinfo/info.xml")->version ?? '');
$OC_VersionString = '';
require "$tree/version.php";
$found = ['server' => $OC_VersionString, 'deck' => $appVersion('deck'), 'spreed' => $appVersion('spreed')];
if ($found !== $expected) {
    fwrite(STDERR, 'tree holds ' . json_encode($found) . ', expected ' . json_encode($expected) . "\n");
    exit(1);
}

$recipientPins = json_decode(file_get_contents(__DIR__ . '/recipient-sources.json'), true, 512, JSON_THROW_ON_ERROR)[$major];
if ($appVersion('circles') !== ($recipientPins['circles']['manifestVersion'] ?? $recipientPins['circles']['version'])) {
    throw new RuntimeException('Circles source version does not match recipient-sources.json');
}
$mailPins = MailSourcePins::verified($tree, (string)$major);

$classes = array_keys((new LibScanner(dirname(__DIR__, 3) . '/lib'))->classes());
$classes = array_values(array_unique([...$classes, ...NextcloudApiUsage::EXTRA_CLASSES, ...array_map(
    static fn (array $gate): string => explode('::', $gate['fallback'])[0],
    NextcloudApiUsage::VERSION_GATED,
)]));
sort($classes);

$parser = new SourceParser($tree);
$surfaces = [];
foreach ($classes as $class) {
    $surfaces[$class] = $parser->surface($class);
}

$header = "<?php\n// Generated by tests/fixtures/nextcloud-api/generate.php from nextcloud/server v{$found['server']}, "
    . "nextcloud/deck v{$found['deck']} and nextcloud/spreed v{$found['spreed']}. Do not edit by hand.\n"
    . "// One class per line; null means the release does not have it. A parameter ending in \"?\" is optional.\n\n";
FixtureFile::write(__DIR__ . "/$major.php", $header,
    ['sources' => $found, 'recipientSources' => $recipientPins, 'mailSources' => $mailPins, 'classes' => $surfaces]);
echo "wrote $major.php: " . count(array_filter($surfaces)) . ' of ' . count($surfaces) . " classes found\n";
